import{_ as a,C as o,o as e,c as s,a2 as n,b as i,w as d,a as c,E as l,a3 as p}from"./chunks/framework.CZqXuAiL.js";const f=JSON.parse('{"title":"Map Layout","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/architecture/maps.md","filePath":"openshield-xdp/architecture/maps.md","lastUpdated":1783232968000}'),h={name:"openshield-xdp/architecture/maps.md"};function g(b,t,_,u,m,P){const r=o("Mermaid");return e(),s("div",null,[t[1]||(t[1]=n('<h1 id="map-layout" tabindex="-1">Map Layout <a class="header-anchor" href="#map-layout" aria-label="Permalink to &quot;Map Layout&quot;">​</a></h1><p>OpenShield-XDP uses <strong>20 pinned BPF maps</strong> shared between the XDP data path (kernel) and the Go loader/alerter (userspace). All maps are pinned to <code>/sys/fs/bpf/openshield/</code> and survive loader restarts.</p><h2 id="complete-map-catalog" tabindex="-1">Complete Map Catalog <a class="header-anchor" href="#complete-map-catalog" aria-label="Permalink to &quot;Complete Map Catalog&quot;">​</a></h2><h3 id="_1-configuration-maps" tabindex="-1">1. Configuration Maps <a class="header-anchor" href="#_1-configuration-maps" aria-label="Permalink to &quot;1. Configuration Maps&quot;">​</a></h3><h4 id="config-map" tabindex="-1"><code>config_map</code> <a class="header-anchor" href="#config-map" aria-label="Permalink to &quot;`config_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_ARRAY</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (index 0)</td></tr><tr><td><strong>Value</strong></td><td><code>struct config</code></td></tr><tr><td><strong>Max Entries</strong></td><td>1</td></tr><tr><td><strong>Pin</strong></td><td><code>LIBBPF_PIN_BY_NAME</code></td></tr><tr><td><strong>Access</strong></td><td>Userspace: write (startup, config reload). Kernel: read (every packet).</td></tr><tr><td><strong>Purpose</strong></td><td>Holds all runtime thresholds, flags, and feature toggles. The single source of truth for pipeline behavior.</td></tr></tbody></table><h4 id="baseline-map" tabindex="-1"><code>baseline_map</code> <a class="header-anchor" href="#baseline-map" aria-label="Permalink to &quot;`baseline_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_ARRAY</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (index 0)</td></tr><tr><td><strong>Value</strong></td><td><code>struct baseline</code></td></tr><tr><td><strong>Max Entries</strong></td><td>1</td></tr><tr><td><strong>Pin</strong></td><td><code>LIBBPF_PIN_BY_NAME</code></td></tr><tr><td><strong>Access</strong></td><td>Userspace: write (baseline EMA every 5s). Kernel: read (window reset).</td></tr><tr><td><strong>Purpose</strong></td><td>Dynamic mitigation baseline and attack state classification. Loaded from <code>baseline.json</code> on warm restart.</td></tr></tbody></table><h3 id="_2-whitelist-maps" tabindex="-1">2. Whitelist Maps <a class="header-anchor" href="#_2-whitelist-maps" aria-label="Permalink to &quot;2. Whitelist Maps&quot;">​</a></h3><h4 id="whitelist-map" tabindex="-1"><code>whitelist_map</code> <a class="header-anchor" href="#whitelist-map" aria-label="Permalink to &quot;`whitelist_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_HASH</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (IPv4 address, host byte order)</td></tr><tr><td><strong>Value</strong></td><td><code>u32</code> (flag bitmask)</td></tr><tr><td><strong>Max Entries</strong></td><td>10,000</td></tr><tr><td><strong>Memory</strong></td><td>~640 KB</td></tr><tr><td><strong>Access</strong></td><td>Userspace: write (config load). Kernel: read (every packet, before ban check).</td></tr><tr><td><strong>Purpose</strong></td><td>IPv4 whitelist. Flag values: <code>0</code> = full bypass (skip all checks); non-zero = bitmask (<code>WL_SKIP_BAN</code>, <code>WL_SKIP_VALIDATION</code>, <code>WL_SKIP_RATE</code>).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">HASH vs LRU</p><p>Whitelist maps use <code>BPF_MAP_TYPE_HASH</code> (not LRU) because whitelist entries must <strong>never</strong> be evicted under memory pressure. They are only removed by explicit userspace delete.</p></div><h4 id="whitelist-map-v6" tabindex="-1"><code>whitelist_map_v6</code> <a class="header-anchor" href="#whitelist-map-v6" aria-label="Permalink to &quot;`whitelist_map_v6`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_HASH</code></td></tr><tr><td><strong>Key</strong></td><td><code>struct ip6_key</code> (hi/lo 64-bit halves)</td></tr><tr><td><strong>Value</strong></td><td><code>u32</code> (flag bitmask)</td></tr><tr><td><strong>Max Entries</strong></td><td>10,000</td></tr><tr><td><strong>Memory</strong></td><td>~960 KB</td></tr></tbody></table><h3 id="_3-per-ip-statistics-maps" tabindex="-1">3. Per-IP Statistics Maps <a class="header-anchor" href="#_3-per-ip-statistics-maps" aria-label="Permalink to &quot;3. Per-IP Statistics Maps&quot;">​</a></h3><h4 id="ip-stats-map" tabindex="-1"><code>ip_stats_map</code> <a class="header-anchor" href="#ip-stats-map" aria-label="Permalink to &quot;`ip_stats_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_LRU_HASH</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (IPv4)</td></tr><tr><td><strong>Value</strong></td><td><code>struct ip_stats</code></td></tr><tr><td><strong>Max Entries</strong></td><td>100,000</td></tr><tr><td><strong>Memory</strong></td><td>~17 MB</td></tr><tr><td><strong>Access</strong></td><td>Kernel: write (every packet, counter increments). Kernel: read (window reset). Userspace: read (top offenders every 5s).</td></tr><tr><td><strong>Purpose</strong></td><td>Per-IP rate counters (PPS, BPS, protocol counts), suspicion score, token bucket state, and advanced metrics. LRU eviction handles map exhaustion during spoofed-source floods.</td></tr></tbody></table><h4 id="ip-stats-map-v6" tabindex="-1"><code>ip_stats_map_v6</code> <a class="header-anchor" href="#ip-stats-map-v6" aria-label="Permalink to &quot;`ip_stats_map_v6`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_LRU_HASH</code></td></tr><tr><td><strong>Key</strong></td><td><code>struct ip6_key</code></td></tr><tr><td><strong>Value</strong></td><td><code>struct ip_stats</code></td></tr><tr><td><strong>Max Entries</strong></td><td>100,000</td></tr><tr><td><strong>Memory</strong></td><td>~17 MB</td></tr></tbody></table><h3 id="_4-ban-maps" tabindex="-1">4. Ban Maps <a class="header-anchor" href="#_4-ban-maps" aria-label="Permalink to &quot;4. Ban Maps&quot;">​</a></h3><h4 id="ban-map" tabindex="-1"><code>ban_map</code> <a class="header-anchor" href="#ban-map" aria-label="Permalink to &quot;`ban_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_LRU_HASH</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (IPv4)</td></tr><tr><td><strong>Value</strong></td><td><code>struct ban_entry</code> (score, expiry, reason, star_level)</td></tr><tr><td><strong>Max Entries</strong></td><td>50,000</td></tr><tr><td><strong>Memory</strong></td><td>~1.3 MB</td></tr><tr><td><strong>Access</strong></td><td>Kernel: write (ban trigger), read (every packet). Userspace: read (ban list), write (expiry cleanup).</td></tr><tr><td><strong>Purpose</strong></td><td>Active single-IP bans with expiry. <strong>Kept across loader restarts</strong> (bans persist).</td></tr></tbody></table><h4 id="ban-map-v6" tabindex="-1"><code>ban_map_v6</code> <a class="header-anchor" href="#ban-map-v6" aria-label="Permalink to &quot;`ban_map_v6`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_LRU_HASH</code></td></tr><tr><td><strong>Key</strong></td><td><code>struct ip6_key</code></td></tr><tr><td><strong>Value</strong></td><td><code>struct ban_entry</code></td></tr><tr><td><strong>Max Entries</strong></td><td>50,000</td></tr><tr><td><strong>Memory</strong></td><td>~1.6 MB</td></tr></tbody></table><h4 id="subnet-ban-map" tabindex="-1"><code>subnet_ban_map</code> <a class="header-anchor" href="#subnet-ban-map" aria-label="Permalink to &quot;`subnet_ban_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_LPM_TRIE</code></td></tr><tr><td><strong>Key</strong></td><td><code>struct lpm_v4_key</code> (prefixlen + IP)</td></tr><tr><td><strong>Value</strong></td><td><code>struct subnet_ban_entry</code> (expiry, reason)</td></tr><tr><td><strong>Max Entries</strong></td><td>1,024</td></tr><tr><td><strong>Flags</strong></td><td><code>BPF_F_NO_PREALLOC</code></td></tr><tr><td><strong>Memory</strong></td><td>~64 KB</td></tr><tr><td><strong>Purpose</strong></td><td>CIDR-based bans. Lookup uses longest-prefix match — a key with <code>prefixlen=32</code> matches all subnet entries containing that IP.</td></tr></tbody></table><h4 id="subnet-ban-map-v6" tabindex="-1"><code>subnet_ban_map_v6</code> <a class="header-anchor" href="#subnet-ban-map-v6" aria-label="Permalink to &quot;`subnet_ban_map_v6`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_LPM_TRIE</code></td></tr><tr><td><strong>Key</strong></td><td><code>struct lpm_v6_key</code></td></tr><tr><td><strong>Value</strong></td><td><code>struct subnet_ban_entry</code></td></tr><tr><td><strong>Max Entries</strong></td><td>512</td></tr><tr><td><strong>Flags</strong></td><td><code>BPF_F_NO_PREALLOC</code></td></tr></tbody></table><h4 id="prefix-ban-map" tabindex="-1"><code>prefix_ban_map</code> <a class="header-anchor" href="#prefix-ban-map" aria-label="Permalink to &quot;`prefix_ban_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_LRU_HASH</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (/24 prefix in host byte order)</td></tr><tr><td><strong>Value</strong></td><td><code>u32</code> (ban count for this /24)</td></tr><tr><td><strong>Max Entries</strong></td><td>1,024</td></tr><tr><td><strong>Memory</strong></td><td>~32 KB</td></tr><tr><td><strong>Purpose</strong></td><td>Tracks how many single-IP bans have occurred in each /24. When the count exceeds <code>auto_escalation_threshold</code>, a subnet ban is automatically inserted into <code>subnet_ban_map</code>.</td></tr></tbody></table><h4 id="prefix-ban-map-v6" tabindex="-1"><code>prefix_ban_map_v6</code> <a class="header-anchor" href="#prefix-ban-map-v6" aria-label="Permalink to &quot;`prefix_ban_map_v6`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_LRU_HASH</code></td></tr><tr><td><strong>Key</strong></td><td><code>struct ip6_key</code> (/64 prefix, lo zeroed)</td></tr><tr><td><strong>Value</strong></td><td><code>u32</code> (ban count for this /64)</td></tr><tr><td><strong>Max Entries</strong></td><td>512</td></tr><tr><td><strong>Memory</strong></td><td>~24 KB</td></tr></tbody></table><h3 id="_5-global-state-maps" tabindex="-1">5. Global State Maps <a class="header-anchor" href="#_5-global-state-maps" aria-label="Permalink to &quot;5. Global State Maps&quot;">​</a></h3><h4 id="global-stats-map" tabindex="-1"><code>global_stats_map</code> <a class="header-anchor" href="#global-stats-map" aria-label="Permalink to &quot;`global_stats_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_PERCPU_ARRAY</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (index 0)</td></tr><tr><td><strong>Value</strong></td><td><code>struct global_stats</code></td></tr><tr><td><strong>Max Entries</strong></td><td>1</td></tr><tr><td><strong>Memory</strong></td><td>~1 KB per CPU</td></tr><tr><td><strong>Access</strong></td><td>Kernel: write (every packet, PERCPU = no lock). Userspace: read (every 1s, sums per-CPU values).</td></tr><tr><td><strong>Purpose</strong></td><td>Global packet/byte counts, drop/pass counters, and attack state flags. PERCPU means zero lock contention.</td></tr></tbody></table><h4 id="new-source-map" tabindex="-1"><code>new_source_map</code> <a class="header-anchor" href="#new-source-map" aria-label="Permalink to &quot;`new_source_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_ARRAY</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (index 0)</td></tr><tr><td><strong>Value</strong></td><td><code>struct new_source_state</code> (bpf_spin_lock + count + window_start)</td></tr><tr><td><strong>Max Entries</strong></td><td>1</td></tr><tr><td><strong>Memory</strong></td><td>&lt; 1 KB</td></tr><tr><td><strong>Access</strong></td><td>Kernel: write (new IP creation, spinlock-protected).</td></tr><tr><td><strong>Purpose</strong></td><td>Global counter tracking how many new IPs were created in the current window. When <code>count</code> exceeds <code>new_source_limit</code>, all new IPs are banned.</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Spinlock Required</p><p><code>new_source_map</code> is the only map that uses <code>struct bpf_spin_lock</code>. Unlike PERCPU maps, this counter must be globally consistent (not per-CPU) because the flood threshold is a single global value.</p></div><h4 id="panic-bucket-map" tabindex="-1"><code>panic_bucket_map</code> <a class="header-anchor" href="#panic-bucket-map" aria-label="Permalink to &quot;`panic_bucket_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_PERCPU_ARRAY</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (index 0)</td></tr><tr><td><strong>Value</strong></td><td><code>struct panic_bucket</code> (pkt_count + last_second)</td></tr><tr><td><strong>Max Entries</strong></td><td>1</td></tr><tr><td><strong>Memory</strong></td><td>&lt; 1 KB per CPU</td></tr><tr><td><strong>Purpose</strong></td><td>Per-CPU rolling second counter for panic drop. When a CPU exceeds <code>panic_pps_rate</code>, packets are probabilistically dropped.</td></tr></tbody></table><h3 id="_6-profiling-map" tabindex="-1">6. Profiling Map <a class="header-anchor" href="#_6-profiling-map" aria-label="Permalink to &quot;6. Profiling Map&quot;">​</a></h3><h4 id="prof-map" tabindex="-1"><code>prof_map</code> <a class="header-anchor" href="#prof-map" aria-label="Permalink to &quot;`prof_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_PERCPU_ARRAY</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (0-26, see slot table below)</td></tr><tr><td><strong>Value</strong></td><td><code>u64</code> (counter)</td></tr><tr><td><strong>Max Entries</strong></td><td>27</td></tr><tr><td><strong>Memory</strong></td><td>~216 B per CPU</td></tr><tr><td><strong>Purpose</strong></td><td>Hot-path profiling. Incremented via <code>prof_inc(PROF_*)</code> at strategic points. Userspace reads every 5s for <code>openshield status</code> diagnostics.</td></tr></tbody></table><p><strong>Profile Slots:</strong></p><table tabindex="0"><thead><tr><th>Index</th><th>Constant</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td><code>PROF_NON_IPV4</code></td><td>Non-IP packets passed</td></tr><tr><td>1</td><td><code>PROF_MALFORMED</code></td><td>Malformed IP packets dropped</td></tr><tr><td>2</td><td><code>PROF_BANNED</code></td><td>Packets dropped by ban check</td></tr><tr><td>3</td><td><code>PROF_WHITELISTED</code></td><td>Whitelist hits</td></tr><tr><td>4</td><td><code>PROF_NO_CONFIG</code></td><td>Packets before config loaded</td></tr><tr><td>5</td><td><code>PROF_PRIVATE_SRC</code></td><td>Private/bogon source IP</td></tr><tr><td>6</td><td><code>PROF_BOGUS_TCP</code></td><td>Invalid TCP flags</td></tr><tr><td>7</td><td><code>PROF_MALFORMED_L4</code></td><td>Truncated L4 payload</td></tr><tr><td>8</td><td><code>PROF_NEW_SRC_CREATE</code></td><td>New IP stats entries created</td></tr><tr><td>9</td><td><code>PROF_NEW_SRC_FLOOD</code></td><td>New-source flood drops</td></tr><tr><td>10</td><td><code>PROF_RATE_DROP</code></td><td>Rate limit drops</td></tr><tr><td>11</td><td><code>PROF_PASSED</code></td><td>Packets passed to kernel</td></tr><tr><td>12</td><td><code>PROF_IP_STATS_HIT</code></td><td>Existing IP stats lookups</td></tr><tr><td>13</td><td><code>PROF_TOTAL</code></td><td>Total packets processed</td></tr><tr><td>14</td><td><code>PROF_PANIC_DROP</code></td><td>Panic breaker drops</td></tr><tr><td>15</td><td><code>PROF_DNS_AMPLIFY</code></td><td>DNS amplification drops</td></tr><tr><td>16</td><td><code>PROF_L7_DROP</code></td><td>L7 signature drops</td></tr><tr><td>17</td><td><code>PROF_UDP_AMP</code></td><td>Generic UDP amp drops</td></tr><tr><td>18</td><td><code>PROF_SYN_FIN_DROP</code></td><td>SYN/FIN ratio drops</td></tr><tr><td>19</td><td><code>PROF_ENTROPY_DROP</code></td><td>Entropy spoofing drops</td></tr><tr><td>20</td><td><code>PROF_TTL_ANOMALY</code></td><td>TTL anomaly drops</td></tr><tr><td>21</td><td><code>PROF_PKT_ANOMALY</code></td><td>Packet size anomaly drops</td></tr><tr><td>22</td><td><code>PROF_CONN_RATE</code></td><td>Connection rate drops</td></tr><tr><td>23</td><td><code>PROF_MAC_DROP</code></td><td>MAC filter drops</td></tr><tr><td>24</td><td><code>PROF_ESCALATION</code></td><td>Auto-escalation subnet bans</td></tr><tr><td>25</td><td><code>PROF_SYNPROXY_SYNACK</code></td><td>SYNs accounted by the scalar SYN gate</td></tr><tr><td>26</td><td><code>PROF_SYNPROXY_DROP</code></td><td>SYN gate drops (reserved; baseline never drops, used by opt-in freplace)</td></tr></tbody></table><h3 id="_7-event-map" tabindex="-1">7. Event Map <a class="header-anchor" href="#_7-event-map" aria-label="Permalink to &quot;7. Event Map&quot;">​</a></h3><h4 id="events-map" tabindex="-1"><code>events_map</code> <a class="header-anchor" href="#events-map" aria-label="Permalink to &quot;`events_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_RINGBUF</code></td></tr><tr><td><strong>Key</strong></td><td>N/A (ring buffer)</td></tr><tr><td><strong>Value</strong></td><td><code>struct event</code></td></tr><tr><td><strong>Max Entries</strong></td><td>262,144 (256 KB)</td></tr><tr><td><strong>Access</strong></td><td>Kernel: write (rate-limited to <code>event_rate_limit</code>/s). Userspace: read (continuous goroutine).</td></tr><tr><td><strong>Purpose</strong></td><td>Event stream for alerting. Full buffer → new writes fail silently → events dropped. Never blocks the packet path.</td></tr></tbody></table><h3 id="_8-l7-signature-map" tabindex="-1">8. L7 Signature Map <a class="header-anchor" href="#_8-l7-signature-map" aria-label="Permalink to &quot;8. L7 Signature Map&quot;">​</a></h3><h4 id="l7-sig-map" tabindex="-1"><code>l7_sig_map</code> <a class="header-anchor" href="#l7-sig-map" aria-label="Permalink to &quot;`l7_sig_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_ARRAY</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (0-15)</td></tr><tr><td><strong>Value</strong></td><td><code>struct l7_sig</code> (proto, port, offset, mask, pattern, min_payload)</td></tr><tr><td><strong>Max Entries</strong></td><td>16</td></tr><tr><td><strong>Memory</strong></td><td>~1 KB</td></tr><tr><td><strong>Feature Gate</strong></td><td>None — all 16 slots are always compiled and available on every supported kernel</td></tr><tr><td><strong>Purpose</strong></td><td>Configurable byte-pattern matching at fixed offsets. Disabled slots have <code>proto == 0</code>.</td></tr></tbody></table><h3 id="_9-bloom-filter-map" tabindex="-1">9. Bloom Filter Map <a class="header-anchor" href="#_9-bloom-filter-map" aria-label="Permalink to &quot;9. Bloom Filter Map&quot;">​</a></h3><h4 id="bloom-map" tabindex="-1"><code>bloom_map</code> <a class="header-anchor" href="#bloom-map" aria-label="Permalink to &quot;`bloom_map`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>BPF_MAP_TYPE_ARRAY</code></td></tr><tr><td><strong>Key</strong></td><td><code>u32</code> (word index, 0-149,999)</td></tr><tr><td><strong>Value</strong></td><td><code>u64</code> (64-bit word, each bit is one Bloom position)</td></tr><tr><td><strong>Max Entries</strong></td><td>150,000</td></tr><tr><td><strong>Memory</strong></td><td>150,000 × 8 = <strong>1.2 MB</strong> (9.6 million bits)</td></tr><tr><td><strong>Access</strong></td><td>Userspace: write (config reload, 3 writes per whitelisted IP). Kernel: read (every packet).</td></tr><tr><td><strong>Purpose</strong></td><td>Fast Bloom filter for whitelist membership. See <a href="./bloom-filter">Bloom Filter</a>.</td></tr></tbody></table><h2 id="memory-budget" tabindex="-1">Memory Budget <a class="header-anchor" href="#memory-budget" aria-label="Permalink to &quot;Memory Budget&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Map</th><th>Entries</th><th>Entry Size (approx)</th><th>Total</th></tr></thead><tbody><tr><td><code>config_map</code></td><td>1</td><td>~300 B</td><td>&lt; 1 KB</td></tr><tr><td><code>baseline_map</code></td><td>1</td><td>~64 B</td><td>&lt; 1 KB</td></tr><tr><td><code>whitelist_map</code></td><td>10,000</td><td>8 B (key + value)</td><td>~640 KB</td></tr><tr><td><code>whitelist_map_v6</code></td><td>10,000</td><td>20 B</td><td>~960 KB</td></tr><tr><td><code>ip_stats_map</code></td><td>100,000</td><td>~170 B</td><td>~17 MB</td></tr><tr><td><code>ip_stats_map_v6</code></td><td>100,000</td><td>~170 B</td><td>~17 MB</td></tr><tr><td><code>ban_map</code></td><td>50,000</td><td>~26 B</td><td>~1.3 MB</td></tr><tr><td><code>ban_map_v6</code></td><td>50,000</td><td>~32 B</td><td>~1.6 MB</td></tr><tr><td><code>subnet_ban_map</code></td><td>1,024</td><td>~32 B</td><td>~64 KB</td></tr><tr><td><code>subnet_ban_map_v6</code></td><td>512</td><td>~40 B</td><td>~40 KB</td></tr><tr><td><code>prefix_ban_map</code></td><td>1,024</td><td>8 B</td><td>~32 KB</td></tr><tr><td><code>prefix_ban_map_v6</code></td><td>512</td><td>24 B</td><td>~24 KB</td></tr><tr><td><code>new_source_map</code></td><td>1</td><td>~16 B</td><td>&lt; 1 KB</td></tr><tr><td><code>global_stats_map</code></td><td>1 (per-CPU)</td><td>~64 B</td><td>~1 KB/CPU</td></tr><tr><td><code>prof_map</code></td><td>27 (per-CPU)</td><td>8 B</td><td>~216 B/CPU</td></tr><tr><td><code>panic_bucket_map</code></td><td>1 (per-CPU)</td><td>16 B</td><td>~16 B/CPU</td></tr><tr><td><code>events_map</code></td><td>256 KB</td><td>—</td><td>256 KB</td></tr><tr><td><code>l7_sig_map</code></td><td>16</td><td>~64 B</td><td>~1 KB</td></tr><tr><td><code>bloom_map</code></td><td>150,000</td><td>8 B</td><td>1.2 MB</td></tr><tr><td><strong>Total</strong></td><td></td><td></td><td><strong>~32 MB</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Memory is pre-allocated</p><p>BPF maps allocate their full memory at creation time (or at first access for <code>BPF_F_NO_PREALLOC</code>). The ~32 MB is reserved in kernel memory and cannot be swapped.</p></div><h2 id="pinning-behavior" tabindex="-1">Pinning Behavior <a class="header-anchor" href="#pinning-behavior" aria-label="Permalink to &quot;Pinning Behavior&quot;">​</a></h2><p>All maps use <code>LIBBPF_PIN_BY_NAME</code> and are pinned under <code>/sys/fs/bpf/openshield/</code>. This means:</p><ul><li><strong>Loader restart</strong>: maps survive. The new loader calls <code>ebpf.LoadPinnedMap()</code> instead of creating new ones.</li><li><strong>Ban persistence</strong>: banned IPs remain banned across restarts.</li><li><strong>Stats persistence</strong>: per-IP counters survive (though the loader typically clears <code>ip_stats_map</code> on restart to avoid stale data).</li></ul><h3 id="clear-on-restart-maps" tabindex="-1">Clear-on-Restart Maps <a class="header-anchor" href="#clear-on-restart-maps" aria-label="Permalink to &quot;Clear-on-Restart Maps&quot;">​</a></h3><p>The loader clears these maps on startup:</p><ul><li><code>ip_stats_map</code> / <code>ip_stats_map_v6</code> — per-IP counters reset to zero</li><li><code>prof_map</code> — profiling counters reset</li></ul><p>These maps are <strong>preserved</strong> across restarts:</p><ul><li><code>ban_map</code> / <code>ban_map_v6</code> — active bans survive</li><li><code>subnet_ban_map</code> / <code>subnet_ban_map_v6</code> — CIDR bans survive</li><li><code>baseline_map</code> — loaded from <code>baseline.json</code></li></ul><h2 id="empty-map-fast-path" tabindex="-1">Empty-Map Fast Path <a class="header-anchor" href="#empty-map-fast-path" aria-label="Permalink to &quot;Empty-Map Fast Path&quot;">​</a></h2><p>When maps are empty at startup (no whitelist entries, no bans), the loader sets two boolean flags in <code>config_map</code>:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cfg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">whitelist_empty </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // skip whitelist + Bloom lookups</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cfg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bans_empty      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // skip ban/subnet/prefix lookups</span></span></code></pre></div><p>These flags are checked at the <strong>start of each relevant pipeline section</strong> before any map lookup, saving 5+ map operations per packet. When entries are added (e.g., a ban is triggered), the flags are updated automatically via the config reload mechanism.</p><h2 id="map-access-patterns" tabindex="-1">Map Access Patterns <a class="header-anchor" href="#map-access-patterns" aria-label="Permalink to &quot;Map Access Patterns&quot;">​</a></h2>',70)),(e(),i(p,null,{default:d(()=>[l(r,{id:"mermaid-2020",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20%22Every%20Packet%22%0A%20%20%20%20%20%20%20%20CFG%5B%22config_map%3Cbr%2F%3E(read)%22%5D%20%0A%20%20%20%20%20%20%20%20WL%5B%22whitelist_map%3Cbr%2F%3E(read)%22%5D%0A%20%20%20%20%20%20%20%20BLOOM%5B%22bloom_map%3Cbr%2F%3E(read)%22%5D%0A%20%20%20%20%20%20%20%20BAN%5B%22ban_map%3Cbr%2F%3E(read)%22%5D%0A%20%20%20%20%20%20%20%20SUBNET%5B%22subnet_ban_map%3Cbr%2F%3E(read)%22%5D%0A%20%20%20%20%20%20%20%20PROF%5B%22prof_map%3Cbr%2F%3E(write)%22%5D%0A%20%20%20%20%20%20%20%20GLOBAL%5B%22global_stats_map%3Cbr%2F%3E(write)%22%5D%0A%20%20%20%20%20%20%20%20PANIC%5B%22panic_bucket_map%3Cbr%2F%3E(write)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Per%20IP%20(stats%20hit)%22%0A%20%20%20%20%20%20%20%20IPSTATS%5B%22ip_stats_map%3Cbr%2F%3E(read%2Bwrite)%22%5D%0A%20%20%20%20%20%20%20%20PREFIX%5B%22prefix_ban_map%3Cbr%2F%3E(read%2Bwrite)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Window%20Reset%22%0A%20%20%20%20%20%20%20%20BASELINE%5B%22baseline_map%3Cbr%2F%3E(read)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Config%20Reload%22%0A%20%20%20%20%20%20%20%20CFG_W%5B%22config_map%3Cbr%2F%3E(write)%22%5D%0A%20%20%20%20%20%20%20%20WL_W%5B%22whitelist_map%3Cbr%2F%3E(write)%22%5D%0A%20%20%20%20%20%20%20%20BLOOM_W%5B%22bloom_map%3Cbr%2F%3E(write)%22%5D%0A%20%20%20%20%20%20%20%20L7_W%5B%22l7_sig_map%3Cbr%2F%3E(write)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Alert%20Path%22%0A%20%20%20%20%20%20%20%20EVENTS%5B%22events_map%3Cbr%2F%3E(write)%22%5D%0A%20%20%20%20end%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[c(" Loading... ",-1)])]),_:1}))])}const k=a(h,[["render",g]]);export{f as __pageData,k as default};
